#ifndef ANALYSIS_H
#define ANALYSIS_H

typedef struct {
    double moisture_raw;
    double light_lux;
    double moisture_change_per_hour;
    double light_exposure_lux_hours;
} plant_snapshot;

typedef enum {
    PLANT_STATUS_INVALID = -1,
    PLANT_STATUS_STABLE = 0,
    PLANT_STATUS_WATER_SOON,
    PLANT_STATUS_NOT_ENOUGH_LIGHT,
    PLANT_STATUS_WATER_AND_LIGHT
} plant_status;

plant_status analyze_plant_snapshot(const plant_snapshot *snapshot);
const char *plant_status_name(plant_status status);

#endif
#include "analysis.h"

#include <math.h>
#include <stddef.h>

plant_status analyze_plant_snapshot(const plant_snapshot *snapshot)
{
    if (snapshot == NULL ||
        !isfinite(snapshot->moisture_raw) ||
        !isfinite(snapshot->light_lux) ||
        !isfinite(snapshot->light_exposure_lux_hours) ||
        !isfinite(snapshot->moisture_change_per_hour) ||
        snapshot->moisture_raw < 0.0 ||
        snapshot->light_lux < 0.0 ||
        snapshot->light_exposure_lux_hours < 0.0) {
        return PLANT_STATUS_INVALID;
    }

    /*
     * Temporary thresholds for testing purposes.
     * Replace them after choosing the plant and calibrating the sensors.
     */
    int needs_water = snapshot->moisture_raw < 350.0;
    int needs_more_light = snapshot->light_exposure_lux_hours < 10000.0;

    if (needs_water && needs_more_light) {
        return PLANT_STATUS_WATER_AND_LIGHT;
    }

    if (needs_water) {
        return PLANT_STATUS_WATER_SOON;
    }

    if (needs_more_light) {
        return PLANT_STATUS_NOT_ENOUGH_LIGHT;
    }

    return PLANT_STATUS_STABLE;
}

const char *plant_status_name(plant_status status)
{
    switch (status) {
    case PLANT_STATUS_STABLE:
        return "STABLE";
    case PLANT_STATUS_WATER_SOON:
        return "WATER_SOON";
    case PLANT_STATUS_NOT_ENOUGH_LIGHT:
        return "NOT_ENOUGH_LIGHT";
    case PLANT_STATUS_WATER_AND_LIGHT:
        return "WATER_AND_LIGHT";
    case PLANT_STATUS_INVALID:
    default:
        return "INVALID";
    }
}
#include "analysis.h"

#include <stdio.h>
#include <string.h>

int main(int argc, char **argv)
{
    const plant_snapshot example = {320.0, 1800.0, -9.5, 12500.0};
    plant_status status;

    if (argc != 2 || strcmp(argv[1], "--simulate") != 0) {
        fprintf(stderr, "usage: %s --simulate\n", argv[0]);
        fprintf(stderr, "live I2C sensor capture is not implemented yet\n");
        return 2;
    }

    status = analyze_plant_snapshot(&example);
    printf("SIMULATED moisture_raw=%.1f light_lux=%.1f "
           "moisture_change_per_hour=%.1f light_exposure_lux_hours=%.1f "
           "status=%s\n",
           example.moisture_raw,
           example.light_lux,
           example.moisture_change_per_hour,
           example.light_exposure_lux_hours,
           plant_status_name(status));
    return 0;
}

#include "analysis.h"

#include <assert.h>
#include <stdio.h>
#include <string.h>

int main(void)
{
    const plant_snapshot stable =
        {500.0, 1800.0, -1.0, 12500.0};

    const plant_snapshot not_enough_light =
        {500.0, 200.0, -1.0, 7000.0};

    const plant_snapshot water_soon =
        {320.0, 1800.0, -9.5, 12500.0};

    const plant_snapshot water_and_light =
        {320.0, 200.0, -9.5, 7000.0};

    const plant_snapshot invalid =
        {-1.0, 200.0, 0.0, 100.0};

    assert(analyze_plant_snapshot(NULL) ==
           PLANT_STATUS_INVALID);

    assert(analyze_plant_snapshot(&invalid) ==
           PLANT_STATUS_INVALID);

    assert(analyze_plant_snapshot(&stable) ==
           PLANT_STATUS_STABLE);

    assert(analyze_plant_snapshot(&not_enough_light) ==
           PLANT_STATUS_NOT_ENOUGH_LIGHT);

    assert(analyze_plant_snapshot(&water_soon) ==
           PLANT_STATUS_WATER_SOON);

    assert(analyze_plant_snapshot(&water_and_light) ==
           PLANT_STATUS_WATER_AND_LIGHT);

    assert(strcmp(
        plant_status_name(PLANT_STATUS_STABLE),
        "STABLE") == 0);

    assert(strcmp(
        plant_status_name(PLANT_STATUS_NOT_ENOUGH_LIGHT),
        "NOT_ENOUGH_LIGHT") == 0);

    assert(strcmp(
        plant_status_name(PLANT_STATUS_WATER_SOON),
        "WATER_SOON") == 0);

    assert(strcmp(
        plant_status_name(PLANT_STATUS_WATER_AND_LIGHT),
        "WATER_AND_LIGHT") == 0);

    assert(strcmp(
        plant_status_name(PLANT_STATUS_INVALID),
        "INVALID") == 0);

    puts("analysis tests passed");
    return 0;
}
#ifndef SENSORS_I2C_TRANSPORT_H
#define SENSORS_I2C_TRANSPORT_H

#include <stddef.h>
#include <stdint.h>

/*
 * One i2c_device is one 7-bit address on one bus. Each write or read is a
 * single I2C transaction that ends in STOP. There is no combined
 * repeated-start operation: the BH1750 datasheet requires a STOP after every
 * opcode, and the seesaw protocol needs a delay between the register write
 * and the data read, so neither sensor uses one.
 *
 * The device owns whatever its backend holds (a file descriptor for the Linux
 * backend). Drivers borrow a device and never close it.
 *
 * A device starts closed: zero-initialize it (i2c_device dev = {0};) before
 * its first open. Every backend's open refuses a device that is still open,
 * returning INVALID_ARGUMENT and leaving it untouched, so a missing close
 * cannot overwrite and orphan the resource it holds. Close it first.
 *
 * Addresses are 7-bit: every backend's open rejects an address above
 * I2C_ADDRESS_7BIT_MAX (0x7f) with INVALID_ARGUMENT, before changing the
 * device or acquiring any resource (the Linux backend checks it before
 * open() or ioctl(I2C_SLAVE)). Only the range is checked; reserved addresses
 * inside it are not refused here.
 *
 * Backend contract:
 * - The ops table provides all four callbacks. A wrapper whose callback is
 *   NULL returns INVALID_ARGUMENT without calling it and leaves the device
 *   unchanged (a close cannot release what it cannot call).
 * - OS_ERROR always carries the nonzero errno of the failed call. A
 *   condition with no errno (such as read() returning 0) is reported as
 *   OK with the actual byte count, which the wrapper turns into
 *   SHORT_TRANSFER.
 * - wait_us returns only after the full duration has elapsed, retrying
 *   with the remaining time when interrupted (EINTR); it never reports OK
 *   for a partial wait. Wait results carry no byte counts: the wrapper sets
 *   requested_len and transferred_len to 0.
 */

#define I2C_ADDRESS_7BIT_MAX 0x7f

typedef enum {
    I2C_STATUS_OK = 0,
    I2C_STATUS_INVALID_ARGUMENT,
    I2C_STATUS_OS_ERROR,        /* a system call failed; see os_errno */
    I2C_STATUS_SHORT_TRANSFER,  /* bytes moved differ from bytes requested,
                                   fewer or (backend bug) more */
    I2C_STATUS_SCRIPT_MISMATCH  /* mock only: operation not in the script */
} i2c_status;

typedef struct {
    i2c_status status;
    int os_errno;           /* errno captured right after the failed call */
    size_t requested_len;
    size_t transferred_len;
} i2c_result;

typedef struct {
    i2c_result (*write)(void *ctx, const uint8_t *buf, size_t len);
    i2c_result (*read)(void *ctx, uint8_t *buf, size_t len);
    i2c_result (*wait_us)(void *ctx, uint32_t duration_us);
    i2c_result (*close)(void *ctx);
} i2c_device_ops;

typedef struct {
    const i2c_device_ops *ops;  /* NULL once closed */
    void *ctx;
    uint8_t address_7bit;
    int is_simulated;
} i2c_device;

i2c_result i2c_device_write(i2c_device *dev, const uint8_t *buf, size_t len);
i2c_result i2c_device_read(i2c_device *dev, uint8_t *buf, size_t len);
i2c_result i2c_device_wait_us(i2c_device *dev, uint32_t duration_us);
i2c_result i2c_device_close(i2c_device *dev);
const char *i2c_status_name(i2c_status status);

#endif
#ifndef SENSORS_I2C_MOCK_H
#define SENSORS_I2C_MOCK_H

#include "sensors/i2c_transport.h"

/*
 * Scripted, hardware-free I2C device for tests. Every device it opens is
 * marked simulated. Waits are recorded and checked, never slept, so protocol
 * timing is testable without slowing the suite. Uses no heap: the mock lives
 * in caller storage and borrows the step array, which must outlive it.
 *
 * A step is validated before its fail_errno applies: a WRITE step needs
 * expected bytes to compare, so a WRITE step with NULL bytes is a
 * SCRIPT_MISMATCH even when fail_errno is set. A READ step may have NULL
 * bytes only when transfer_len is 0.
 */

typedef enum {
    I2C_MOCK_WRITE,
    I2C_MOCK_READ,
    I2C_MOCK_WAIT
} i2c_mock_op;

typedef struct {
    i2c_mock_op op;
    const uint8_t *bytes;   /* WRITE: expected bytes; READ: bytes returned */
    size_t len;             /* WRITE/READ: expected request length */
    size_t transfer_len;    /* WRITE/READ: bytes the fake bus moves */
    int fail_errno;         /* nonzero: fail with OS_ERROR and this errno */
    uint32_t min_wait_us;   /* WAIT: shortest acceptable wait */
} i2c_mock_step;

typedef struct {
    const i2c_mock_step *steps;
    size_t step_count;
    size_t next_step;
    uint64_t waited_us;     /* total simulated wait time */
    int mismatch;           /* sticky once any operation is unexpected */
    size_t mismatch_step;   /* index of the first unexpected operation */
} i2c_mock;

/* dev must be closed (zeroed or closed by i2c_device_close) and
 * address_7bit must be at most 0x7f; see i2c_transport.h. Returns
 * INVALID_ARGUMENT and leaves dev and mock untouched otherwise. */
i2c_status i2c_mock_open(i2c_mock *mock, i2c_device *dev,
                         uint8_t address_7bit,
                         const i2c_mock_step *steps, size_t step_count);

#endif
